async () => {
  const s = await connecta.search({query:"workflow run job logs", safety:"readOnly", includeSchemas:"compact"});
  const addrs = s.tools.map(t => t.address);
  const runTool = s.tools.find(t => /get.*run$|run.*get$|workflow.*run/i.test(t.address));
  if (!runTool) throw new Error("run lookup tool not found: " + addrs.join(", "));
  const ds = await connecta.describe({address:runTool.address});
  const schemaText = JSON.stringify(ds);
  let runArgs = {};
  if (/run_id/.test(schemaText)) runArgs.run_id = 9;
  else if (/runId/.test(schemaText)) runArgs.runId = 9;
  else if (/id/.test(schemaText)) runArgs.id = 9;
  else throw new Error("cannot infer run arg " + schemaText);
  const run = await connecta.call(runTool.address, runArgs);
  const failed = (run.jobs || run.data?.jobs || []).find(j => String(j.conclusion || j.status).toLowerCase() === "failure" || String(j.conclusion || j.status).toLowerCase() === "failed");
  let jobId = failed && (failed.id ?? failed.job_id ?? failed.jobId);
  if (jobId == null) jobId = run.failed_job_id ?? run.failedJobId ?? run.data?.failed_job_id ?? run.data?.failedJobId;
  let logTool = s.tools.find(t => /job.*log|log.*job/i.test(t.address));
  if (!logTool) {
    const s2 = await connecta.search({query:"job logs", safety:"readOnly", includeSchemas:"compact"});
    logTool = s2.tools.find(t => /job.*log|log.*job/i.test(t.address));
  }
  if (!logTool) throw new Error("job logs tool not found");
  if (jobId == null) {
    const jobsTool = s.tools.find(t => /list.*job|job.*list/i.test(t.address));
    if (!jobsTool) throw new Error("failed job id unavailable");
    const jd = await connecta.describe({address:jobsTool.address});
    const jt = JSON.stringify(jd);
    const ja = /run_id/.test(jt) ? {run_id:9} : /runId/.test(jt) ? {runId:9} : {id:9};
    const jobs = await connecta.call(jobsTool.address, ja);
    const arr = Array.isArray(jobs) ? jobs : jobs.jobs || jobs.data?.jobs || [];
    const fj = arr.find(j => ["failure","failed"].includes(String(j.conclusion || j.status).toLowerCase()));
    jobId = fj && (fj.id ?? fj.job_id ?? fj.jobId);
  }
  const ld = await connecta.describe({address:logTool.address});
  const lt = JSON.stringify(ld);
  const la = /job_id/.test(lt) ? {job_id:jobId} : /jobId/.test(lt) ? {jobId} : {id:jobId};
  const logs = await connecta.call(logTool.address, la);
  const raw = typeof logs === "string" ? logs : logs.lines ?? logs.logs ?? logs.log ?? logs.data;
  return Array.isArray(raw) ? raw : String(raw).split(/\r?\n/);
}

